import type { JSONSupport } from "../../../../core/JSONSupport.js";

export interface ChoiceProperties extends Partial<Pick<Choice, "label" | "value">> {}

/**
 * Defines a choice in a [MultipleChoiceInput](https://developers.arcgis.com/javascript/latest/references/core/form/elements/inputs/MultipleChoiceInput/).
 *
 * @since 5.1
 */
export default class Choice extends JSONSupport {
  constructor(properties?: ChoiceProperties);
  /**
   * The label shown for the choice.
   *
   * @default ""
   */
  accessor label: string;
  /**
   * The stored value for the choice.
   *
   * @default ""
   */
  accessor value: string;
  /**
   * Creates a deep clone of the `Choice` class.
   *
   * @returns A deep clone of the `Choice` instance.
   */
  clone(): Choice;
}